## 1. Harmonic algebra $\mathfrak H$

$$
X := \mathbb R_{>0}
$$

$$
R, L, O : X \to X
$$

$$
\boxed{\;
R(x) = \tfrac{2}{3}x,\qquad
L(x) = \tfrac{3}{4}x,\qquad
O(x) = \tfrac{1}{2}x
\;}
$$

$$
\kappa_{\mathrm{cl}} : X \times X \times X \to X,
\qquad
\kappa_{\mathrm{cl}}(c, r, l) := \frac{r\,l}{c}
$$

$$
\boxed{\;
\mathfrak H
=
\Bigl\langle
X;\,
R,\,L,\,O,\,\kappa_{\mathrm{cl}}
\;\Bigm|\;
R L = L R = O,\;
\kappa_{\mathrm{cl}}(x, R x, L x) = O x
\Bigr\rangle
\;}
$$

Logarithmic coordinates:

$$
\ell_{R} := \log_{2}\tfrac{2}{3},\qquad
\ell_{L} := \log_{2}\tfrac{3}{4},\qquad
\ell_{O} := \log_{2}\tfrac{1}{2} = -1
$$

$$
\boxed{\;
\ell_{R} + \ell_{L} = \ell_{O} = -1
\;}
$$

$$
\langle R, L \rangle \;\cong\; \mathbb Z^{2}
\quad
\text{with basis } (1,-1),\ (-2,1) \in \mathbb Z^{2}
$$

---

## 2. Relational pitch structure

$$
\boxed{\;
r_{ij} = \frac{f_{j}}{f_{i}},
\qquad
d_{ij} = \log_{2} r_{ij}
\;}
$$

$$
\boxed{\;
r_{ik} = r_{ij}\,r_{jk},
\qquad
d_{ik} = d_{ij} + d_{jk}
\;}
$$

$$
\boxed{\;
\mathcal Q_{n}
=
\mathbb R^{n} / \operatorname{span}(\mathbf 1),
\qquad
D_{R} := \dim \mathcal Q_{n} = n - 1
\;}
$$

$\mathcal R_{\mathrm{int}}$ denotes the interval/composition structure on $\mathcal Q_{n}$:

$$
\mathcal R_{\mathrm{int}} := \bigl(\,\{r_{ij}\},\; \{\cdot\},\; \{+\}\,\bigr)
$$

Typed distinctness of dimensionalities:

$$
\boxed{\;
D_{R} \not\equiv D_{P} \not\equiv D_{O}
\;}
$$

where $\not\equiv$ is conceptual/type non-identity, not a numeric inequality. Numerical coincidences are not presumed.

